Let me design `pprint`:

```go
// Package pprint renders arbitrary Go values in a deep, human-readable form
// intended for debugging and inspection.
//
// Unlike fmt's %v/%#v, the printer follows pointers, expands interfaces,
// renders unexported struct fields, and detects reference cycles so that
// self-referential data does not cause unbounded recursion.
package pprint

import (
	"io"
	"os"

	"github.com/davecgh/go-spew/spew"
)

// Default is the configuration used by the package-level helpers.
// It is tuned for inspection rather than compact output:
//
//   - methods are not invoked, so printing never has side effects
//   - output is indented and map keys are sorted for stable diffs
//   - pointer addresses are shown so shared/aliased values are obvious
//   - there is no depth limit; cycles are handled by go-spew
var Default = &Printer{
	state: &spew.ConfigState{
		Indent:                  "    ",
		MaxDepth:                0,
		DisableMethods:          true,
		DisablePointerMethods:   true,
		DisablePointerAddresses: false,
		DisableCapacities:       false,
		ContinueOnMethod:        false,
		SortKeys:                true,
		SpewKeys:                true,
	},
}

// Printer wraps a go-spew configuration so callers can tune output.
type Printer struct {
	state *spew.ConfigState
}

// New returns a Printer that writes with the given indent unit.
func New(indent string) *Printer {
	c := *Default.state
	if indent != "" {
		c.Indent = indent
	}
	return &Printer{state: &c}
}

// Sdump returns the deep representation of the supplied values as a string.
func (p *Printer) Sdump(values ...interface{}) string {
	return p.state.Sdump(values...)
}

// Fdump writes the deep representation of values to w.
func (p *Printer) Fdump(w io.Writer, values ...interface{}) {
	p.state.Fdump(w, values...)
}

// Dump writes the deep representation of values to standard error.
func (p *Printer) Dump(values ...interface{}) {
	p.state.Fdump(os.Stderr, values...)
}

// Package-level helpers using Default.

func Sdump(values ...interface{}) string { return Default.Sdump(values...) }
func Fdump(w io.Writer, values ...interface{}) { Default.Fdump(w, values...) }
func Dump(values ...interface{}) { Default.Dump(values...) }
```

