// Package pprint renders arbitrary Go values in a deep, human-readable form
// intended for interactive debugging and inspection.
//
// It improves on fmt's %v/%#v verbs in the cases that matter most while
// debugging:
//
//   - pointers and interfaces are followed and expanded recursively;
//   - unexported struct fields are included, not hidden;
//   - reference cycles terminate instead of recursing forever;
//   - shared values are visible through their pointer addresses;
//   - output is indented with sorted map keys, so it diffs cleanly.
//
// Printing never invokes user-defined String or Format methods, so arbitrary
// values can be dumped without triggering side effects.
package pprint

import (
	"io"
	"os"

	"github.com/davecgh/go-spew/spew"
)

// Default is the configuration used by the package-level helpers. It is tuned
// for inspection rather than compact output.
var Default = &Printer{
	state: &spew.ConfigState{
		Indent:                  "    ",
		MaxDepth:                0,
		DisableMethods:          true,
		DisablePointerMethods:   true,
		DisablePointerAddresses: false,
		DisableCapacities:       false,
		ContinueOnMethod:        false,
		SortKeys:                true,
		SpewKeys:                true,
	},
}

// Printer renders values using a specific configuration.
type Printer struct {
	state *spew.ConfigState
}

// New returns a Printer that indents the output with the given unit. An empty
// indent falls back to the Default indentation.
func New(indent string) *Printer {
	c := *Default.state
	if indent != "" {
		c.Indent = indent
	}
	return &Printer{state: &c}
}

// Sdump returns the deep representation of the supplied values as a string.
func (p *Printer) Sdump(values ...interface{}) string {
	return p.state.Sdump(values...)
}

// Fdump writes the deep representation of values to w.
func (p *Printer) Fdump(w io.Writer, values ...interface{}) {
	p.state.Fdump(w, values...)
}

// Dump writes the deep representation of values to standard error.
func (p *Printer) Dump(values ...interface{}) {
	p.state.Fdump(os.Stderr, values...)
}

// Sdump returns the deep representation of values using Default.
func Sdump(values ...interface{}) string { return Default.Sdump(values...) }

// Fdump writes the deep representation of values to w using Default.
func Fdump(w io.Writer, values ...interface{}) { Default.Fdump(w, values...) }

// Dump writes the deep representation of values to standard error using Default.
func Dump(values ...interface{}) { Default.Dump(values...) }

package pprint

import (
	"bytes"
	"strings"
	"testing"
)

type secret struct {
	Exported int
	hidden   string
}

type node struct {
	Name string
	Next *node
}

func TestDumpIncludesUnexportedFields(t *testing.T) {
	out := Sdump(secret{Exported: 1, hidden: "shh"})
	for _, want := range []string{"secret", "Exported", "1", "hidden", "shh"} {
		if !strings.Contains(out, want) {
			t.Errorf("Sdump output missing %q:\n%s", want, out)
		}
	}
}

func TestDumpTerminatesOnCycles(t *testing.T) {
	a := &node{Name: "a"}
	a.Next = a

	out := Sdump(a)
	if !strings.Contains(out, "Next") {
		t.Fatalf("cycle was not rendered:\n%s", out)
	}
	if len(out) > 4096 {
		t.Fatalf("cycle produced unbounded output (%d bytes)", len(out))
	}
}

func TestDumpIsDeterministicForMaps(t *testing.T) {
	m := map[string]int{"b": 2, "a": 1, "c": 3}
	first := Sdump(m)
	for i := 0; i < 20; i++ {
		if got := Sdump(m); got != first {
			t.Fatalf("map output not deterministic:\n%s\nvs\n%s", first, got)
		}
	}
}

func TestDumpExpandsInterfacesAndPointers(t *testing.T) {
	var v interface{} = []int{1, 2, 3}
	out := Sdump(v)
	if !strings.Contains(out, "[]int") {
		t.Errorf("interface was not expanded to its dynamic type:\n%s", out)
	}
}

func TestFdumpWritesToWriter(t *testing.T) {
	var buf bytes.Buffer
	Fdump(&buf, 42)
	if !strings.Contains(buf.String(), "42") {
		t.Errorf("Fdump wrote %q", buf.String())
	}
}

func TestNewIndent(t *testing.T) {
	var buf bytes.Buffer
	New("\t").Fdump(&buf, secret{Exported: 7, hidden: "x"})
	if !strings.Contains(buf.String(), "\t") {
		t.Errorf("custom indent was not applied:\n%s", buf.String())
	}
}

// Command deepdump demonstrates the pprint package by dumping a few
// representative Go values: a self-referential graph, a nested map, and a
// struct with unexported fields.
package main

import (
	"fmt"

	"godebug/pprint"
)

type person struct {
	Name    string
	Age     int
	secrets []string
}

type linked struct {
	Value int
	Next  *linked
}

func main() {
	pprint.Dump(person{
		Name:    "Ada",
		Age:     36,
		secrets: []string{"loves analytical engines"},
	})

	n := &linked{Value: 1, Next: &linked{Value: 2}}
	n.Next.Next = n
	pprint.Dump(n)

	pprint.Dump(map[string][]int{
		"primes": {2, 3, 5, 7},
		"evens":  {2, 4, 6},
	})

	fmt.Println(pprint.Sdump(struct{ Any interface{} }{Any: map[string]string{"k": "v"}}))
}

// Command deepdump demonstrates the pprint package by dumping a few
// representative Go values: a self-referential graph, a nested map, and a
// struct with unexported fields.
package main

import (
	"os"

	"godebug/pprint"
)

type person struct {
	Name    string
	Age     int
	secrets []string
}

type linked struct {
	Value int
	Next  *linked
}

func main() {
	pprint.Fdump(os.Stdout, person{
		Name:    "Ada",
		Age:     36,
		secrets: []string{"loves analytical engines"},
	})

	n := &linked{Value: 1, Next: &linked{Value: 2}}
	n.Next.Next = n
	pprint.Fdump(os.Stdout, n)

	pprint.Fdump(os.Stdout, map[string][]int{
		"primes": {2, 3, 5, 7},
		"evens":  {2, 4, 6},
	})
}

